  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  padding: 0 1.5rem;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.site-logo {
  font-size: 1.5rem;
  line-height: 1;
}

.site-name {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--clr-accent);
}

/* ── Main & hero ────────────────────────────────────────────────── */
main {
  flex: 1;
  padding: 0 1.5rem 4rem;
}

main:focus {
  outline: none;
}

.hero {
  max-width: var(--max-width);
  margin: 3rem auto 2.5rem;
  text-align: center;
}

.hero h1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.2;
}

.hero-subtitle {
  margin-top: 0.75rem;
  font-size: 1.0625rem;
  color: var(--clr-text-secondary);
}

