.faq-section {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Each disclosure item ───────────────────────────────────────── */
.example {
  background: var(--clr-surface);
