  border-color: var(--clr-border-hover);
  box-shadow: var(--shadow-card-hover);
}

.example h3 {
  margin: 0;
}

.example h3 button {
  all: unset;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.125rem 1.375rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--clr-text-primary);
  cursor: pointer;
  gap: 1rem;
  line-height: 1.4;
}

.example h3 button::after {
  content: "";
